package com.hrcoresystem.hrcore_api.modules.tenant.departments.application.usecase;
import com.hrcoresystem.hrcore_api.modules.platform.tenantsettings.application.service.TenantTimezoneService; import com.hrcoresystem.hrcore_api.modules.tenant.departments.application.dto.OrganizationalEmployeeSummaryResponse; import com.hrcoresystem.hrcore_api.modules.tenant.departments.domain.repository.DepartmentRepository; import com.hrcoresystem.hrcore_api.modules.tenant.employees.domain.repository.OrganizationalEmployeeQueryRepository; import com.hrcoresystem.hrcore_api.common.exception.ResourceNotFoundException; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.UUID;
@Service public class ListDepartmentEmployeesUseCase { private final OrganizationalEmployeeQueryRepository repo; private final TenantTimezoneService timezone; private final DepartmentRepository departments; public ListDepartmentEmployeesUseCase(OrganizationalEmployeeQueryRepository r,TenantTimezoneService t,DepartmentRepository d){repo=r;timezone=t;departments=d;} public Page<OrganizationalEmployeeSummaryResponse> execute(UUID id,LocalDate date,Pageable p){if(departments.findById(id).isEmpty()) throw new ResourceNotFoundException("Departamento no encontrado"); return repo.findByDepartment(id,date==null?timezone.today():date,p);} }
